mapper.select:
/* 그날 미션이 출제된 반려동물 조회 */
SELECT DISTINCT PET_SN
  FROM DAY_MSN
 WHERE MSN_CRTR_YMD = #{msnCrtrYmd}

mapper.insert:
/* 일별미션 등록 */
INSERT INTO DAY_MSN
     ( CARE_MSN_SN
     , PET_SN
     , MBR_SN
     , MSN_CRTR_YMD
     , SCOR_PNT
     , REG_DT
     , MDFCN_DT
     )
VALUES
     ( #{careMsnSn}
     , #{petSn}
     , #{mbrSn}
     , #{msnCrtrYmd}
     , #{scorPnt}
     , NOW()
     , NOW()
     )

mapper.select:
/* 반려동물의 그날 미션 잠금 조회 */
SELECT 
  FROM DAY_MSN D
  JOIN PET P
    ON P.PET_SN = D.PET_SN
   AND P.DEL_YN = 'N'
 WHERE D.PET_SN = #{petSn}
   AND D.MSN_CRTR_YMD = #{msnCrtrYmd}
   AND D.CARE_MSN_SN = #{careMsnSn}
   FOR UPDATE

/* 회원 앞으로 출제된 그날 미션 잠금 조회(펫이야기 = 대표 반려동물 1마리) */
SELECT 
  FROM DAY_MSN D
  JOIN PET P
    ON P.PET_SN = D.PET_SN
   AND P.DEL_YN = 'N'
 WHERE D.MBR_SN = #{mbrSn}
   AND D.MSN_CRTR_YMD = #{msnCrtrYmd}
   AND D.CARE_MSN_SN = #{careMsnSn}
 ORDER BY D.DAY_MSN_SN
 LIMIT 1
   FOR UPDATE

mapper.update:
/* 일별미션 진행 횟수 수정 */
UPDATE DAY_MSN
   SET PRGRS_NMTM = #{prgrsNmtm}
     , MDFCN_DT = NOW()
 WHERE DAY_MSN_SN = #{dayMsnSn}
   AND CMPTN_YN = 'N'

/* 일별미션 완료(즉시 지급 포인트 기록) */
UPDATE DAY_MSN
   SET PRGRS_NMTM = #{prgrsNmtm}
     , CMPTN_MBR_SN = #{cmptnMbrSn}
     , GIVE_PNT = #{givePnt}
     , CMPTN_DT = NOW()
     , CMPTN_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE DAY_MSN_SN = #{dayMsnSn}
   AND CMPTN_YN = 'N'

/* 일별미션 정산 확정 */
UPDATE DAY_MSN
   SET GIVE_PNT = #{givePnt}
     , CLCLN_CFMTN_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE DAY_MSN_SN = #{dayMsnSn}
   AND CLCLN_CFMTN_YN = 'N'

mapper.select:
/* 회원의 그날 미션 집계(주양육 반려동물 전체) */
SELECT COUNT(CASE WHEN D.CMPTN_YN = 'Y' THEN 1 END) AS CMPTN_MSN_CNT
     , COUNT(*)                                     AS MSN_CNT
     , COUNT(DISTINCT D.PET_SN)                     AS PET_CNT
  FROM DAY_MSN D
  JOIN PET P
    ON P.PET_SN = D.PET_SN
   AND P.DEL_YN = 'N'
 WHERE D.MBR_SN = #{mbrSn}
   AND D.MSN_CRTR_YMD = #{msnCrtrYmd}

/* 반려동물 이름 조회 */
SELECT PET_NM
  FROM PET
 WHERE PET_SN = #{petSn}
   AND DEL_YN = 'N'
